 * Protocol Abstraction Layer (PAL) - Header
 * 
 * Provides a unified interface for CAN bus, RS485, and EtherCAT protocols.
 * Abstracts the underlying transport to provide consistent motor control.
 */

#ifndef PAL_H
#define PAL_H

#include <Arduino.h>
#include <ArduinoJson.h>

// Frame types (from PROTOCOLS_CONTRACT.md)
enum class FrameType : uint8_t {
    STATUS_REPORT      = 0x01,
    POSITION_CMD       = 0x02,
    VELOCITY_CMD       = 0x03,
    TORQUE_CMD         = 0x04,
    PARAM_READ         = 0x05,
    PARAM_WRITE        = 0x06,
    DIAGNOSTIC         = 0x07,
    FIRMWARE_UPDATE    = 0x08,
    HEARTBEAT          = 0x09,
    RESERVED           = 0x0A
};

// Motor series enumeration
enum class MotorSeries : uint8_t {
    RMD_X = 0x01,
    RH    = 0x02,
    CEM   = 0x03,
    RMD_H = 0x04,
    RMD_L = 0x05,
    FL    = 0x06
};

// Protocol enumeration
enum class Protocol : uint8_t {
    CAN       = 0x01,
    RS485     = 0x02,
    ETHERCAT  = 0x03
};

// Drive type
enum class DriveType : uint8_t {
    BIDIRECTIONAL = 0x01,
    UNIDIRECTIONAL = 0x02
};

// Gearbox type
enum class GearboxType : uint8_t {
    PLANETARY = 0x01,
    HARMONIC  = 0x02,
    CYCLOID   = 0x03,
    DIRECT    = 0x04
};

// Communication interface
enum class Communication : uint8_t {
    CAN       = 0x01,
    RS485     = 0x02,
    ETHERCAT  = 0x03
};

// Motor configuration structure
struct MotorConfig {
    MotorSeries motorSeries;
    Protocol protocol;
    uint8_t encoderBits;
    uint8_t powerClass;
    GearboxType gearboxType;
    bool hasBrake;
    DriveType driveType;
    Communication communication;
};

// Status report structure (from PROTOCOLS_CONTRACT.md)
struct StatusReport {
    int32_t position;        // 4 bytes
    int32_t velocity;        // 4 bytes
    int16_t torque;          // 2 bytes
    int16_t temperature;     // 2 bytes
    uint16_t voltage;        // 2 bytes
    uint16_t current;        // 2 bytes
    uint8_t statusFlags;     // 1 byte
    uint8_t errorFlags;      // 1 byte
};

// Command structure
struct Command {
    FrameType frameType;
    uint8_t motorId;
    uint8_t payload[64];
    uint8_t payloadLength;
};

// Protocol Abstraction Layer class
class ProtocolAbstractionLayer {
public:
    ProtocolAbstractionLayer();
    ~ProtocolAbstractionLayer();

    // Initialize PAL with motor configuration
    void init(const MotorConfig& config);

    // Process incoming commands
    void processCommands();

    // Send status report
    void sendStatusReport();

    // Send heartbeat
    void sendHeartbeat();

    // Get current status
    StatusReport getStatus() const;

    // Set target position
    void setPosition(int32_t position);

    // Set target velocity
    void setVelocity(int32_t velocity);

    // Set target torque
    void setTorque(int16_t torque);

    // Read parameter
    bool readParameter(uint8_t paramId, uint8_t* data, uint8_t length);

    // Write parameter
    bool writeParameter(uint8_t paramId, const uint8_t* data, uint8_t length);

    // Get protocol name
    String getProtocolName() const;

    // Get motor series name
    String getMotorSeriesName() const;

private:
    MotorConfig _config;
    StatusReport _status;
    bool _initialized;

    // Protocol-specific implementations
    void initCAN();
    void initRS485();
    void initEtherCAT();

    // Command handlers
    void handleStatusReport(const Command& cmd);
    void handlePositionCmd(const Command& cmd);
    void handleVelocityCmd(const Command& cmd);
    void handleTorqueCmd(const Command& cmd);
    void handleParamRead(const Command& cmd);
    void handleParamWrite(const Command& cmd);
    void handleDiagnostic(const Command& cmd);
    void handleFirmwareUpdate(const Command& cmd);
    void handleHeartbeat(const Command& cmd);

    // Frame construction
    uint8_t calculateChecksum(const uint8_t* data, uint8_t length);
    bool validateFrame(const uint8_t* data, uint8_t length);
};

#endif // PAL_H
"}

